def solution():
    import heapq

    # Graph represented as adjacency list: node -> list of (neighbor, weight)
    graph = {
        0: [(1, 2)],
        1: [(3, 7), (4, 7)],
        2: [(0, 1), (1, 3)],
        3: [(0, 2)],
        4: []
    }
    start, end = 0, 4

    # Dijkstra's algorithm
    dist = {node: float('inf') for node in graph}
    prev = {node: None for node in graph}
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == end:
            break
        for v, w in graph.get(u, []):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    # Reconstruct path
    if dist[end] == float('inf'):
        path = []
        total = 0
    else:
        path = []
        cur = end
        while cur is not None:
            path.append(cur)
            cur = prev[cur]
        path.reverse()
        total = dist[end]

    return path, int(total)

