from collections import deque

def solution() -> Dict[int, str]:
    # adjacency list for the given graph
    edges = {
        1: [3, 4, 8],
        2: [4, 7],
        3: [1],
        4: [1, 2],
        5: [8],
        6: [8],
        7: [2],
        8: [1, 5, 6],
    }
    colors: Dict[int, str] = {}
    for v in range(1, 9):
        if v not in colors:
            colors[v] = 'A'  # assign starting color for this component
            q = deque([v])
            while q:
                u = q.popleft()
                cu = colors[u]
                for w in edges[u]:
                    if w not in colors:
                        colors[w] = 'B' if cu == 'A' else 'A'
                        q.append(w)
                    elif colors[w] == cu:
                        raise ValueError('Graph is not bipartite')
    return colors

